-- Candidaturas de Acción de Barrio (25/11/2026), facilitadas por la organización.

INSERT OR IGNORE INTO nominees (category_id, slug, name, subtitle, reason, bio, merits, published, is_alternate, position) SELECT id, 'asociacion-vecinal-esperanza-san-bernardo', 'Asociación Vecinal Esperanza – San Bernardo', 'Asociación vecinal · San Bernardo', 'Un espacio de convivencia, aprendizaje y participación que mantiene viva la actividad social de San Bernardo.', 'La Asociación Vecinal Esperanza impulsa la vida comunitaria de San Bernardo a través de su centro sociocultural, que acoge una biblioteca social, talleres y diferentes actividades dirigidas a los vecinos. Su labor contribuye a crear oportunidades de encuentro, fomentar la participación y fortalecer las relaciones entre generaciones, consolidando un espacio de referencia para la barriada.', 'Organización de un mercadillo prerreyes con artesanía, artículos de segunda mano y un buzón para las cartas a los Reyes Magos (enero).
Convocatoria de una reunión vecinal vinculada al programa ERACIS+ para coordinar iniciativas de desarrollo comunitario en la zona de Levante (septiembre).
Biblioteca social en el centro sociocultural de la calle Castellar.
Talleres de baile, costura y yoga en su centro sociocultural.', 1, 0, 1 FROM categories WHERE slug = 'accion-de-barrio';
INSERT OR IGNORE INTO nominees (category_id, slug, name, subtitle, reason, bio, merits, published, is_alternate, position) SELECT id, 'asociacion-de-vecinos-san-pedro', 'Asociación de Vecinos San Pedro', 'Asociación vecinal · San Pedro', 'Cultura, tradiciones y participación vecinal que convierten su sede en un punto de encuentro para todo el barrio.', 'La Asociación de Vecinos San Pedro mantiene una intensa actividad comunitaria a través de su sede, donde conviven iniciativas culturales, agrupaciones musicales, talleres y encuentros vecinales. Su compromiso con las tradiciones populares y la dinamización social ha convertido este espacio en un lugar de referencia para la convivencia, la creatividad y la participación de los residentes de la barriada.', 'Reunión entre los vecinos afectados de la calle Crespo, representantes municipales, técnicos y la empresa adjudicataria para abordar la reparación de viviendas dañadas por obras anteriores (marzo).
Celebración de las fiestas del barrio de San Pedro, con la participación de la asociación Avanvida (junio).
Incorporación de los Campanilleros del Junquillo al centro vecinal de la calle Santa Ana (septiembre).
Acogida permanente de una comparsa y un grupo de crocheteras en su sede.', 1, 0, 2 FROM categories WHERE slug = 'accion-de-barrio';
INSERT OR IGNORE INTO nominees (category_id, slug, name, subtitle, reason, bio, merits, published, is_alternate, position) SELECT id, 'asociacion-de-vecinos-san-felipe', 'Asociación de Vecinos San Felipe', 'Asociación vecinal · San Felipe', 'Compromiso vecinal y participación ciudadana al servicio de la convivencia y las necesidades de San Felipe.', 'La Asociación de Vecinos San Felipe representa el valor del asociacionismo como herramienta para fortalecer la convivencia y canalizar las inquietudes de los residentes. Su labor se centra en mantener la participación ciudadana, promover la identidad de la barriada y defender sus necesidades, contribuyendo a que los vecinos tengan voz en los asuntos que afectan a su entorno cotidiano.', NULL, 1, 0, 3 FROM categories WHERE slug = 'accion-de-barrio';
INSERT OR IGNORE INTO nominees (category_id, slug, name, subtitle, reason, bio, merits, published, is_alternate, position) SELECT id, 'asociacion-de-vecinos-santiago-conchal-castillo', 'Asociación de Vecinos Santiago-Conchal-Castillo', 'Asociación vecinal · Santiago, Conchal y Castillo', 'Tradiciones populares, actividades culturales y participación comunitaria que mantienen unidos a los vecinos de sus barriadas.', 'La Asociación de Vecinos Santiago-Conchal-Castillo desarrolla una labor de dinamización comunitaria mediante su implicación en actividades culturales, celebraciones populares e iniciativas dirigidas a las familias. Su participación en la vida social de estas barriadas contribuye a preservar las tradiciones, generar espacios de encuentro y fortalecer los vínculos entre sus residentes, poniendo en valor la importancia del movimiento vecinal en La Línea.', 'Organización del tradicional Arrastre de Latas desde la calle Santa Claudia, junto a la sede vecinal (5 de enero).
Entrega de regalos y premios a los niños durante el Arrastre de Latas.', 1, 0, 4 FROM categories WHERE slug = 'accion-de-barrio';
